using Amazon.SecretsManager;
using Amazon.SecretsManager.Model;

var secretsClient = new SecretsManagerClient(RegionEndpoint.USEast1);

var request = new GetSecretValueRequest
{
    SecretId = "aspnet/connectionstrings/default"
};

var response = await secretsClient.GetSecretValueAsync(request);
string connectionString = response.SecretString;
Console.WriteLine(connectionString);

using Amazon.SecretsManager;

var builder = WebApplication.CreateBuilder(args);

var secretsClient = new SecretsManagerClient(RegionEndpoint.USEast1);
builder.Configuration.AddSecretsManager(config =>
{
    config.SecretManager = secretsClient;
    config.MapPath = (name, json) =>
    {
        if (name == "aspnet/connectionstrings/default")
            return ConfigurationPath.Path("ConnectionStrings:Default");
        return name;
    };
});

var connectionString = builder.Configuration.GetConnectionString("Default");
Console.WriteLine(connectionString);
